# Let's analyze each transformation more carefully
inputs = ['cad', 'ibdh', 'gdg', 'hwx', 'bjk']
outputs = ['cexyd', 'cyjdkek', 'gdg', 'kekwj', 'bjk']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find differences character by character
        print("  Differences:")
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                print(f"    Position {j}: '{char_in}' -> '{char_out}'")
        # Check if one string is substring of another
        if len(inp) <= len(outp):
            # Check if inp appears in outp
            if inp in outp:
                print(f"  '{inp}' found in '{outp}'")
        else:
            if outp in inp:
                print(f"  '{outp}' found in '{inp}'")
    print()

